/** `secret_versions` of Sylphx Broker: Resource type `secrets.sylphx.com/SecretVersion`. */
export class SecretVersionsCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Sends one SMS with a pinned same-environment carrier credential in Secrets.
	 * Requires an exact-version broker:sms:send grant and an Idempotency-Key.
	 * Returns only a carrier receipt; never exports credentials or retries on a
	 * different carrier. The credential is a JSON secret payload with provider
	 * "telnyx" and an api_key string. Receipts are retained for 24 hours. If the
	 * outcome is unknown, reconcile with the carrier before attempting a new send.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/secrets/*\/secret_versions/*}:sendCarrierSms` · permission `broker:sms:send` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_FIELD`, `INVALID_STATE`, `RATE_LIMITED`, `UNAVAILABLE`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async sendCarrierSms(request: SendCarrierSmsRequest): Promise<SendCarrierSmsResponse> {
		return this.client.call<SendCarrierSmsResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/secrets/*/secret_versions/*', 'name')}:sendCarrierSms`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.broker.v1.SendCarrierSmsRequest',
			responseType: 'sylphx.broker.v1.SendCarrierSmsResponse',
			mutation: true,
		})
	}

	/**
	 * Reads the delivery state of an accepted Notify SMS using the exact live
	 * SecretVersion and the original send key. Only the attested Notify workload
	 * may read its own recorded acceptance, during the 24-hour receipt window.
	 * Does not send, bill, or return message content or credentials.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/secrets/*\/secret_versions/*}:checkCarrierSmsDelivery` · permission `broker:sms:send` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `INVALID_STATE`, `RESOURCE_NOT_FOUND`, `UNAVAILABLE`.
	 */
	async checkCarrierSmsDelivery(request: CheckCarrierSmsDeliveryRequest): Promise<CheckCarrierSmsDeliveryResponse> {
		return this.client.call<CheckCarrierSmsDeliveryResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/secrets/*/secret_versions/*', 'name')}:checkCarrierSmsDelivery`,
			query: { send_key: request.sendKey },
			responseType: 'sylphx.broker.v1.CheckCarrierSmsDeliveryResponse',
			mutation: false,
		})
	}

	/**
	 * Recovers the supplier acknowledgment for one existing Broker media attempt.
	 * Uses the original tenant and pinned billing SecretVersion. Missing or
	 * incomplete evidence never authorizes dispatch, capture or release.
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/secrets/*\/secret_versions/*}:recoverMediaExecution` · permission `broker:media:recover` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `INVALID_FIELD`, `FAILED_PRECONDITION`, `UNAVAILABLE`.
	 */
	async recoverMediaExecution(request: RecoverMediaExecutionRequest): Promise<RecoverMediaExecutionResponse> {
		return this.client.call<RecoverMediaExecutionResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/secrets/*/secret_versions/*', 'name')}:recoverMediaExecution`,
			query: { execution_key: request.executionKey },
			responseType: 'sylphx.broker.v1.RecoverMediaExecutionResponse',
			mutation: false,
		})
	}

	/**
	 * Validates one bounded media input and quotes the minimum Money reservation.
	 * This operation is pure: it reads no credentials, reserves no money and
	 * cannot send a supplier request. A quote is not dispatch authority.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/secrets/*\/secret_versions/*}:quoteMediaExecution` · permission `broker:media:quote` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `UNAVAILABLE`.
	 */
	async quoteMediaExecution(request: QuoteMediaExecutionRequest): Promise<QuoteMediaExecutionResponse> {
		return this.client.call<QuoteMediaExecutionResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/secrets/*/secret_versions/*', 'name')}:quoteMediaExecution`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.broker.v1.QuoteMediaExecutionRequest',
			responseType: 'sylphx.broker.v1.QuoteMediaExecutionResponse',
			mutation: true,
		})
	}
}

/** `token_exchanges` of Sylphx Broker: Resource type `broker.sylphx.com/TokenExchange`. */
export class TokenExchangesCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets the record of one issued credential.
	 *
	 * `GET /v1/{name=orgs/*\/trust_policies/*\/token_exchanges/*}` · permission `broker:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetTokenExchangeRequest): Promise<TokenExchange> {
		return this.client.call<TokenExchange>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/trust_policies/*/token_exchanges/*', 'name')}`,
			responseType: 'sylphx.broker.v1.TokenExchange',
			mutation: false,
		})
	}

	/**
	 * Lists the credentials issued under a trust policy, newest first.
	 *
	 * `GET /v1/{parent=orgs/*\/trust_policies/*}/token_exchanges` · permission `broker:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListTokenExchangesRequest): Promise<ListTokenExchangesResponse> {
		return this.client.call<ListTokenExchangesResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/trust_policies/*', 'parent')}/token_exchanges`,
			query: { page_size: request.pageSize, page_token: request.pageToken },
			responseType: 'sylphx.broker.v1.ListTokenExchangesResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListTokenExchangesRequest): AsyncGenerator<TokenExchange> {
		let next: ListTokenExchangesRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.tokenExchanges ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}

	/**
	 * Revokes an issued credential at the provider by its record. The Broker
	 * uses the credential it holds sealed, so the caller needs no token and no
	 * live delegation. Idempotent: a credential already revoked or expired
	 * answers the record. Erases the sealed credential once the provider
	 * confirms.
	 *
	 * `POST /v1/{name=orgs/*\/trust_policies/*\/token_exchanges/*}:revoke` · permission `broker:read` · effect `destructive`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `UNAVAILABLE`.
	 */
	async revoke(request: RevokeTokenExchangeRequest): Promise<TokenExchange> {
		return this.client.call<TokenExchange>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/trust_policies/*/token_exchanges/*', 'name')}:revoke`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.broker.v1.RevokeTokenExchangeRequest',
			responseType: 'sylphx.broker.v1.TokenExchange',
			mutation: true,
		})
	}
}
